INSERT INTO `dice_pipeline_template_versions` VALUES (8,8,'custom','1.0','name: custom\nversion: \"1.0\"\ndesc: 自定义模板\n\ntemplate: |\n  version: 1.1\n  stages:','','2020-10-14 10:05:17','2020-10-14 10:05:17'),(9,9,'java-boot-gradle-dice','1.0','name: java-boot-gradle-dice\nversion: \"1.0\"\ndesc: springboot gradle 打包构建部署到 dice 的模板\n\ntemplate: |\n\n  version: 1.1\n  stages:\n    - stage:\n        - git-checkout:\n            params:\n              depth: 1\n    - stage:\n        - java-build:\n            version: \"1.0\"\n            params:\n              build_cmd:\n                - ./gradlew bootJar\n              jdk_version: 8\n              workdir: ${git-checkout}\n    - stage:\n        - release:\n            params:\n              dice_yml: ${git-checkout}/dice.yml\n              services:\n                dice.yml中的服务名:\n                  image: registry.cn-hangzhou.aliyuncs.com/terminus/terminus-openjdk:v11.0.6\n                  copys:\n                    - ${java-build:OUTPUT:buildPath}/build/jar包的路径/jar包的名称:/target/jar包的名称\n                  cmd: java -jar /target/jar包的名称\n\n    - stage:\n        - dice:\n            params:\n              release_id: ${release:OUTPUT:releaseID}\n\n\nparams:\n\n  - name: pipeline_version\n    desc: 生成的pipeline的版本\n    default: \"1.1\"\n    required: false\n\n  - name: pipeline_cron\n    desc: 定时任务的cron表达式\n    required: false\n\n  - name: pipeline_scheduling\n    desc: 流水线调度策略\n    required: false\n','','2020-10-14 10:05:49','2020-10-14 13:35:57'),(10,10,'java-boot-maven-dice','1.0','name: java-boot-maven-dice\nversion: \"1.0\"\ndesc: springboot maven 打包构建部署到 dice 的模板\n\ntemplate: |\n\n  version: 1.1\n  stages:\n    - stage:\n        - git-checkout:\n            params:\n              depth: 1\n\n    - stage:\n        - java-build:\n            version: \"1.0\"\n            params:\n              build_cmd:\n                - mvn package\n              jdk_version: 8\n              workdir: ${git-checkout}\n\n    - stage:\n        - release:\n            params:\n              dice_yml: ${git-checkout}/dice.yml\n              services:\n                dice.yml中的服务名:\n                  image: registry.cn-hangzhou.aliyuncs.com/terminus/terminus-openjdk:v11.0.6\n                  copys:\n                    - ${java-build:OUTPUT:buildPath}/target/jar包的名称:/target/jar包的名称\n                  cmd: java -jar /target/jar包的名称\n\n    - stage:\n        - dice:\n            params:\n              release_id: ${release:OUTPUT:releaseID}\n\n\nparams:\n\n  - name: pipeline_version\n    desc: 生成的pipeline的版本\n    default: \"1.1\"\n    required: false\n\n  - name: pipeline_cron\n    desc: 定时任务的cron表达式\n    required: false\n\n  - name: pipeline_scheduling\n    desc: 流水线调度策略\n    required: false\n','','2020-10-14 10:06:16','2020-10-14 13:36:28'),(11,11,'java-tomcat-maven-dice','1.0','name: java-tomcat-maven-dice\nversion: \"1.0\"\ndesc: java maven 打包构建放入 tomcat 部署到 dice 的模板\n\ntemplate: |\n\n  version: \"1.1\"\n  stages:\n    - stage:\n        - git-checkout:\n            params:\n              depth: 1\n\n    - stage:\n        - java-build:\n            version: \"1.0\"\n            params:\n              build_cmd:\n                - mvn clean package\n              jdk_version: 8\n              workdir: ${git-checkout}\n\n    - stage:\n        - release:\n            params:\n              dice_yml: ${git-checkout}/dice.yml\n              services:\n                dice_yaml中的服务名称:\n                  image: tomcat:jdk8-openjdk-slim\n                  copys:\n                    - ${java-build:OUTPUT:buildPath}/target/war包的名称.war:/usr/local/tomcat/webapps\n                  cmd: mv /usr/local/tomcat/webapps/war包的名称.war /usr/local/tomcat/webapps/ROOT.war && /usr/local/tomcat/bin/catalina.sh run\n\n    - stage:\n        - dice:\n            params:\n              release_id: ${release:OUTPUT:releaseID}\n\n','','2020-10-14 10:06:45','2020-10-14 10:46:26'),(12,12,'js-herd-release-dice','1.0','name: js-herd-release-dice\nversion: \"1.0\"\ndesc: js 直接运行并部署到 dice 的模板\n\ntemplate: |\n\n  version: \"1.1\"\n  stages:\n    - stage:\n        - git-checkout:\n            alias: git-checkout\n            version: \"1.0\"\n    - stage:\n        - js-build:\n            alias: js-build\n            version: \"1.0\"\n            params:\n              build_cmd:\n                - cnpm i\n              workdir: ${git-checkout}\n\n    - stage:\n        - release:\n            alias: release\n            params:\n              dice_yml: ${git-checkout}/dice.yml\n              services:\n                dice.yml中的服务名:\n                  cmd: cd /root/js-build && ls && npm run dev\n                  copys:\n                    - ${js-build}:/root/\n                  image: registry.cn-hangzhou.aliyuncs.com/terminus/terminus-herd:1.1.8-node12\n    - stage:\n        - dice:\n            alias: dice\n            params:\n              release_id: ${release:OUTPUT:releaseID}\n\n','','2020-10-14 10:07:11','2020-10-14 10:07:11'),(13,13,'js-spa-release-dice','1.0','name: js-spa-release-dice\nversion: \"1.0\"\ndesc: js 进行打包构建到 nginx 并部署到 dice 的模板\n\ntemplate: |\n\n  version: \"1.1\"\n  stages:\n    - stage:\n        - git-checkout:\n            alias: git-checkout\n            version: \"1.0\"\n    - stage:\n        - js-build:\n            alias: js-build\n            version: \"1.0\"\n            params:\n              build_cmd:\n                - cnpm i\n                - cnpm run build\n              workdir: ${git-checkout}\n\n    - stage:\n        - release:\n            alias: release\n            params:\n              dice_yml: ${git-checkout}/dice.yml\n              services:\n                dice.yml中的服务名:\n                  cmd: sed -i \"s^server_name .*^^g\" /etc/nginx/conf.d/nginx.conf.template && envsubst \"`printf \'$%s\' $(bash -c \"compgen -e\")`\" < /etc/nginx/conf.d/nginx.conf.template > /etc/nginx/conf.d/default.conf && /usr/local/openresty/bin/openresty -g \'daemon off;\'\n\n                  copys:\n                    - ${js-build}/(build 产出的目录):/usr/share/nginx/html/\n                    - ${js-build}/nginx.conf.template:/etc/nginx/conf.d/\n                  image: registry.cn-hangzhou.aliyuncs.com/dice-third-party/terminus-nginx:0.2\n    - stage:\n        - dice:\n            alias: dice\n            params:\n              release_id: ${release:OUTPUT:releaseID}\n\n','','2020-10-14 10:07:38','2020-10-14 10:07:38');
/*!40000 ALTER TABLE `dice_pipeline_template_versions` ENABLE KEYS */;
UNLOCK TABLES;

