INSERT INTO `fdp_agent_dl_data_model_sensitive_rule` VALUES (0,'不脱敏','不脱敏',0,NULL,NULL,NULL,0),(1,'中文姓名','保留首尾两个汉字，其他用星号代替。如果只有两个汉字，则最后一位用星号代替',1,'(\\S)(\\S)(\\S{0,10})','$1*$3',NULL,0),(2,'身份证号','显示最后四位，其他隐藏。共计18位或者15位，比如：*************1234',2,'(.*)(.{4})','**************$2',NULL,0),(3,'电话','前三位，后四位，其他隐藏，比如：135****6810',3,'(.{3})(.*)(.{4})','$1********$2',NULL,0),(4,'家庭住址','只显示到地区，不显示详细地址，比如：上海徐汇区漕河泾开发区***',4,'(\\S+)(\\u533a|\\u53bf|\\u9547|\\u4e61)(\\S+)','$1$2******',NULL,0),(5,'银行卡号','前六位，后四位，其他用星号隐藏每位1个星号，比如：622260**********1234',5,'(.{6})(.*)(.{4})','$1********$3',NULL,0),(6,'密码','密码的全部字符都用*代替，比如：******',6,'\\S+','********',NULL,0),(7,'邮箱','邮箱前缀仅显示第一个字母，前缀其他隐藏，用星号代替，@及后面的地址显示',7,'(\\w)(\\w+)@(\\w+)','$1***@$3',NULL,0),(8,'通用规则','仅保留第一个与最后一个字符，其余全部***',8,'(.{1})(.*)(.{1})','$1********$3',NULL,0);
/*!40000 ALTER TABLE `fdp_agent_dl_data_model_sensitive_rule` ENABLE KEYS */;
UNLOCK TABLES;

